export const PORTRAIT_KEYS = ["maya", "dev", "jordan", "priya"] as const;

export const PORTRAITS: Record<string, string> = {
  maya:
    "",
  dev:
    "",
  jordan:
    "",
  priya:
    "",
};

export function portraitBytes(key: string): Uint8Array | null {
  if (!Object.prototype.hasOwnProperty.call(PORTRAITS, key)) return null;
  return Uint8Array.from(atob(PORTRAITS[key]), (c) => c.charCodeAt(0));
}

export function isPortraitKey(key: string): boolean {
  return Object.prototype.hasOwnProperty.call(PORTRAITS, key);
}
